import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第86章 考场","description":"","frontmatter":{},"headers":[],"relativePath":"第86章_考场.md","filePath":"第86章_考场.md"}'),r={name:"第86章_考场.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第86章-考场" tabindex="-1">第86章 考场 <a class="header-anchor" href="#第86章-考场" aria-label="Permalink to &quot;第86章 考场&quot;">​</a></h1><p>高三春天最后那场大考落在了多雨的日子。</p><p>早上出门时雾很薄，贴在南雾县的街道上，像一层没有擦净的水汽。巷口推着车卖豆浆的老汉还没收摊，我买了一杯，捧在手心一路走到校门口。杯壁的热度透过纸杯传过来，指尖发烫，心里却凉凉的。</p><p>教学楼前聚满了人。林小满抱着文具袋跑过来，头发被风吹得翘起一角。她说她昨晚没睡好，梦里全是涂卡的声音。我笑她，她又去扯陈默的袖子。陈默还是那副样子，话少，眼下有淡淡的青色。他朝我点点头，算是打过招呼。</p><p>我顺着人流上楼。楼道里全是脚步声和低语，还有人靠在栏杆上背小纸条，嘴唇动得飞快。空气里有粉笔灰的味道，混着雨后墙壁返潮的凉气。</p><p>监考的是老周。他站在门口，抱着卷子，神情比平日松一些。他看了我一眼，说进去吧，别慌。我点头，找自己的位置。</p><p>我的座位在中间偏后。她在左上。</p><p>我一眼就看见了江苒。</p><p>她坐在靠窗的那一列，左上首位。窗外是操场边的香樟，叶子被雨洗过，绿得发亮。她把头发扎得很低，发尾落在校服领口上。她正在摆文具，动作很慢，一支笔，一块橡皮，摆得整整齐齐。</p><p>阳光从窗缝里斜进来，落在她的桌面上，晃出一小片亮。她伸手压了压被风吹起的卷角，指尖白净。</p><p>我坐下，心跳慢慢加快。椅子腿蹭着地面，发出一声轻响。老周抬头看了过来，我赶紧低头。</p><p>铃响了。</p><p>卷子从前往后传。纸张摩擦的声音在教室里此起彼伏，带着油墨的微香。我接过卷子，先写名字。笔尖落在纸上，有点滑。我深吸一口气，告诉自己慢一点。</p><p>这是最后一科。</p><p>考完，这个春天的大考就结束了。所有人都在等这一声铃，像等退潮。</p><p>起初教室很安静，只剩笔尖划过纸面的沙沙声，还有老周来回踱步的脚步声。他穿的是软底鞋，声音很轻，一下，又一下。</p><p>窗外的风一阵一阵。香樟叶晃动，光影在江苒的桌上跳。她写字的速度很快，背挺得很直。我能看见她的侧脸，睫毛垂着，嘴唇轻轻抿着。她思考的时候会停一下，笔尖悬在半空，不动。</p><p>我收回视线，看自己的卷子。题目很长，字密密麻麻。我读了两遍，才慢慢找到思路。手心开始出汗，笔杆有点打滑。我在裤子上蹭了蹭手心，继续写。</p><p>时间过得很慢。墙上的钟走动的声音被放大，滴答，滴答。我不敢抬头看，怕看了更慌。</p><p>不知过了多久，窗外开始飘细雨。雨丝斜斜地打在玻璃上，留下细细的水痕。泥土和青叶的气息从窗缝钻进来，凉凉的，带着一点苦。我闻到前排传来的薄荷油味道，大概是谁抹了提神。混合着纸张的味道，教室里的空气变得潮湿而沉。</p><p>有人翻卷子，哗啦一声。有人小声咳嗽。老周低声说了一句，注意时间。他走到窗边，把开了一半的窗又推小一些，雨声便远了。</p><p>我写到后半部分，思路开始发涩。有道题绕了很久，我在草稿纸上画了又擦，纸面都起了毛。橡皮屑落在桌上，我用手背扫开，碎屑掉在地上，无声。</p><p>我抬头，忍不住又看向左上。</p><p>江苒已经停笔了。</p><p>她靠在椅背上，正望着窗外。雨落在香樟叶上，叶子低垂，又弹起。她的眼神很静，不知道在看雨，还是在发呆。阳光淡了，她的轮廓融在灰白的天光里。</p><p>她低头，翻了翻卷子，又检查了一遍答题卡。然后她合上笔盖。</p><p>咔哒一声，很轻。</p><p>在满室的沙沙声里，那一声却格外清晰。</p><p>老周看了过去。江苒举手，声音不大，说老师，我交卷。</p><p>全班有几个人抬头，又很快低下。我听见林小满那边传来吸气的声音，很短。</p><p>老周走过去，收了她的卷子，低声问她，要不要再看看。她摇摇头，说不用了。她开始收拾桌面，把笔一支支放回笔袋，拉链拉上的声音很利落。</p><p>她站起身，椅子轻轻晃了一下。她把椅子扶正，动作小心，没有发出大的声响。</p><p>她抱着笔袋往外走。经过我身边时，她的脚步放得很慢。校服袖口擦过空气，带来一阵很淡的香。是海盐糖的味道，咸咸甜甜的，混着纸页的旧香。我愣了一下。</p><p>有什么东西轻轻落在我的桌角。</p><p>我低头。</p><p>是一张卡片。</p><p>浅蓝色的，像退潮后留在沙上的水色。上面印着细小的浪纹，边角被磨得有点软，一看就是用了很久。卡片下面，还压着一颗海盐糖。糖纸是透明的，折角整齐。</p><p>我的心猛地跳了一下。</p><p>她没有停留，也没有看我，径直走向门口。老周对她点点头，示意她可以走了。她在门口顿了一下，回头望了一眼教室。</p><p>她的目光扫过左上的窗，又扫过中间的我。很短的一眼，快得像雨点落地。</p><p>然后她转身，走进了楼道里的光里。</p><p>教室重新安静下来。雨声渐渐密了，敲在玻璃上，细细密密。我捏着那颗糖，糖纸发出极轻的脆响。同桌皱眉看了我一眼，我赶紧把手缩回桌下。</p><p>卡片贴着桌面，凉凉的。我用指腹摩挲了一下，浪纹凹凸不平。那是她最喜欢的卡片，开学时夹在书里，我见过很多次。她说在旧书店淘的，闻起来有海的味道。</p><p>她为什么在这个时候给我。</p><p>我把卡片翻过来，背面写着很小的字。是用铅笔写的，笔画很轻，要凑近才能看清。</p><p>我还没看清，老周已经走到我身边。他轻轻敲了敲我的桌子，低声说，专心。</p><p>我赶紧把卡片塞进文具袋，低头看卷子。可那些字已经浮在眼前，挥不去。笔尖停在纸上，墨水洇出一个小点。</p><p>剩下的时间，我写得很乱。脑子里全是她起身的样子，还有那句我交卷。她走得那样干脆，像是早就决定好了。窗外的雨越来越大，香樟在雨里摇晃，左上那个座位空着，桌面干净，椅子摆得端正。阳光彻底没了，那一角暗下来，像退潮后露出的空滩。</p><p>铃声终于响了。</p><p>老周说停笔。教室里一阵骚动，有人叹气，有人笑。林小满趴在桌上，长长出了一口气。陈默交了卷，站在门口等我们。顾远和何晓在走廊上大声说话，声音里都是松快。</p><p>我走出考场，楼道里挤满了人。雨停了，风带着水汽扑在脸上，凉丝丝的。我摸了摸口袋里的卡片和糖，糖纸的棱角硌着掌心。</p><p>我在人群里找她。</p><p>走廊尽头，江苒站在栏杆边，正望着操场。雨后的云散开，天光白亮。她头发上落了一点水汽，肩线瘦削。何晓跑过去拍她的肩，她回头笑了笑。</p><p>我走过去，想问她卡片背面的字是什么意思。还没开口，她先看了我一眼，眼神亮亮的，带着一点狡黠。</p><p>她说，考完了。</p><p>我说，嗯。</p><p>她又说，糖给你带的，压压惊。</p><p>我握紧那颗糖，说，你怎么提前交了。</p><p>她望向远处的香樟，顿了顿，说，想早点去看潮。</p><p>我愣住。南雾县靠海，退潮时滩涂会露出来。她以前说过，喜欢退潮后的味道，咸的，空的，干净的。</p><p>她转头看我，轻声说，我把位子让出来了，左上，看得最清楚。</p><p>我还想再问，她却从口袋里摸出一颗同样的糖，剥开，放进嘴里。糖纸在她指间皱成一团，发出脆响。她眯起眼睛，像是尝到了咸味，又像是笑了。</p><p>集合的哨声远远响起，人群开始往楼下涌。陈默喊我的名字，林小满招手让我快点。</p><p>江苒把那团糖纸放在我手心，说，回去再看。</p><p>说完她转身，混入人流。风吹起她的发尾，很快不见了。</p><p>我站在原地，手心里的糖纸还带着她的温度。文具袋里的卡片紧贴着拉链，背面的铅笔字隔着布料发烫。</p><p>我忽然很想知道，那上面到底写了什么。</p><p>而楼下，哨声又响了一遍，比刚才更急。</p>',68)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
